import "server-only";
import { db } from "@/lib/db";
import { withUsageTransaction } from "@/lib/usage-ledger";
import { cancelQueuedIn } from "@/lib/cancellation";
import type { GmailPauseReason } from "@/generated/prisma/enums";
import type { Prisma } from "@/generated/prisma/client";

export { sendingPause } from "@/lib/gmail-pause";
export async function pauseOwnerIn(
  tx: Prisma.TransactionClient,
  userId: string,
  reason: GmailPauseReason,
  until: Date | null,
) {
  const credential =
    reason === "RECONNECT_REQUIRED" || reason === "DOMAIN_POLICY";
  // Preserve the longest provider cooldown; credential/policy pauses require an
  // authorized reconnect and cannot be shortened by another in-flight request.
  const current = await tx.user.findUniqueOrThrow({
    where: { id: userId },
    select: { gmailPauseReason: true, gmailPauseUntil: true },
  });
  if (
    !credential &&
    ["RECONNECT_REQUIRED", "DOMAIN_POLICY"].includes(
      current.gmailPauseReason ?? "",
    )
  )
    return;
  await tx.user.updateMany({
    where: { id: userId },
    data: {
      gmailPauseReason:
        !credential &&
        current.gmailPauseReason === "PROVIDER_DAILY_LIMIT" &&
        current.gmailPauseUntil &&
        until &&
        current.gmailPauseUntil > until
          ? current.gmailPauseReason
          : reason,
      gmailPauseUntil:
        !credential &&
        current.gmailPauseUntil &&
        until &&
        current.gmailPauseUntil > until
          ? current.gmailPauseUntil
          : until,
      ...(credential ? { gmailAuthorized: false } : {}),
    },
  });
  if (credential) await cancelQueuedIn(tx, userId);
}
export async function pauseOwner(
  userId: string,
  reason: GmailPauseReason,
  until: Date | null,
) {
  return withUsageTransaction(db, userId, ({ tx }) =>
    pauseOwnerIn(tx, userId, reason, until),
  );
}
export async function pauseGmailProject(until: Date) {
  await db.$transaction(async (tx) => {
    // No owner lock here. Claims take SHARE on this row, so a committed pause
    // fences every final claim that follows it without locking during network IO.
    await tx.$executeRaw`UPDATE "SystemControl" SET "gmailProjectPauseUntil"=GREATEST(COALESCE("gmailProjectPauseUntil",${until}),${until}) WHERE key='global'`;
  });
}
